import {ApiApplicationsEnum} from "../services/enum/enum-api-aplications";

export interface AdydFormConfig {
    api: ApiApplicationsEnum;
    operationId: string;
}

import {InjectionToken} from "@angular/core";

export interface NavigablePayLoad<T = unknown> {
    type: 'campaign' | 'character';
    id: number | string;
    data: T
}


export interface AdydLink {

    routeLinkService<T>(path: string, payload?: NavigablePayLoad<T>) : void
}

export const API_ROUTER: InjectionToken<AdydLink> = new InjectionToken('API_ROUTER');

import {InjectionToken} from '@angular/core';
import {ApiApplicationsEnum} from "./enum/enum-api-aplications";
import {Observable} from "rxjs";

export interface ApiApplications {

    executeService(api: ApiApplicationsEnum, data: Record<string, string|number|File>, operationId: string) : Observable<any>
}

export const API_APPLICATIONS: InjectionToken<ApiApplications> = new InjectionToken('API_APPLICATIONS');

import {InjectionToken} from "@angular/core";

export interface AuthService {

    hasPermission(permission: string[]): boolean;
    logout(): void;
    getUser(): string;
}

export const AUTH_SERVICE = new InjectionToken<AuthService>('AUTH_SERVICE');

export interface CardItem {
  id: number;
  url: string;
  title: string;
  description: string;
}

import { Component, computed, signal } from '@angular/core';
import { AdydCard } from '../../lib/adyd-card/adyd-card';
import { AdydSpinner } from '../../lib/adyd-spinner/adyd-spinner';

type ButtonTheme =
  | 'primary'
  | 'secondary'
  | 'success'
  | 'warning'
  | 'info'
  | 'danger'
  | 'dark'
  | 'light';

type ButtonStyle = 'solid' | 'outline' | 'subtle' | 'text';

type CardTheme = 'parchment' | 'crimson' | 'gold' | 'arcane';

type SpinnerSize = 'sm' | 'md' | 'lg';

interface ColorToken {
  name: string;
  token: string;
  value: string;
  usage: string;
}

interface CardThemeToken {
  key: CardTheme;
  label: string;
  bg: string;
  border: string;
  ink: string;
  accent: string;
}

interface TabItem {
  id: string;
  label: string;
  title: string;
  body: string;
}

@Component({
  selector: 'adyd-style-guide',
  imports: [AdydCard, AdydSpinner],
  templateUrl: './style-guide.component.html',
  styleUrl: './style-guide.component.css',
})
export class StyleGuideComponent {

  protected readonly buttonThemes: ReadonlyArray<{ key: ButtonTheme; label: string }> = [
    { key: 'primary', label: 'Carmesí' },
    { key: 'secondary', label: 'Pergamino' },
    { key: 'success', label: 'Oro' },
    { key: 'warning', label: 'Latón' },
    { key: 'info', label: 'Arcano' },
    { key: 'danger', label: 'Sangre' },
    { key: 'dark', label: 'Tinieblas' },
    { key: 'light', label: 'Luz' },
  ];

  protected readonly buttonStyles: ReadonlyArray<{ key: ButtonStyle; label: string }> = [
    { key: 'solid', label: 'Sólidos' },
    { key: 'outline', label: 'Contorno' },
    { key: 'subtle', label: 'Sutiles' },
    { key: 'text', label: 'Texto' },
  ];

  protected readonly colors: ReadonlyArray<ColorToken> = [
    { name: 'Pergamino', token: '--bg-surface', value: '#fbf5e6', usage: 'Fondo principal' },
    { name: 'Pergamino oscuro', token: '--bg-surface-alt', value: '#e8dcc4', usage: 'Fondos alternos' },
    { name: 'Pestaña inactiva', token: '--bg-tab-inactive', value: '#e3d4b7', usage: 'Pestañas' },
    { name: 'Tinta', token: '--text-main', value: '#23170d', usage: 'Texto principal' },
    { name: 'Tinta suave', token: '--text-muted', value: '#5c4632', usage: 'Texto secundario' },
    { name: 'Borde', token: '--border-ink', value: '#7a5c3c', usage: 'Bordes y marcos' },
    { name: 'Carmesí', token: '--accent-crimson', value: '#8b1e1e', usage: 'Acento principal' },
    { name: 'Oro', token: '--accent-gold', value: '#c59b27', usage: 'Acento secundario' },
  ];

  protected readonly cardThemes: ReadonlyArray<CardThemeToken> = [
    {
      key: 'parchment',
      label: 'Pergamino',
      bg: '#fbf5e6',
      border: '#8c6d31',
      ink: '#7a5c3c',
      accent: '#8b1e1e',
    },
    {
      key: 'crimson',
      label: 'Carmesí',
      bg: '#f7e6dc',
      border: '#8b1e1e',
      ink: '#5b1414',
      accent: '#c59b27',
    },
    {
      key: 'gold',
      label: 'Oro',
      bg: '#fdf3d8',
      border: '#c59b27',
      ink: '#7a5c1f',
      accent: '#8b1e1e',
    },
    {
      key: 'arcane',
      label: 'Arcano',
      bg: '#e7eef6',
      border: '#24476e',
      ink: '#132740',
      accent: '#7ea8be',
    },
  ];

  protected readonly spinnerSizes: ReadonlyArray<SpinnerSize> = ['sm', 'md', 'lg'];

  protected readonly spinnerVariants: ReadonlyArray<'astrolabe' | 'd20'> = ['astrolabe', 'd20'];

  protected readonly tabs: ReadonlyArray<TabItem> = [
    {
      id: 'pergamino',
      label: 'Pergamino',
      title: 'El pergamino',
      body: 'La base del tema: superficies cálidas, tinta marrón y marcos dorados. Ideal para fichas, libros de campaña y paneles de lectura.',
    },
    {
      id: 'carmesi',
      label: 'Carmesí',
      title: 'La marca carmesí',
      body: 'El acento de la casa: rojo profundo para acciones principales, sellos de lacre y estados de peligro.',
    },
    {
      id: 'arcano',
      label: 'Arcano',
      title: 'El sello arcano',
      body: 'Azules de grimorio para información, magia y elementos secundarios que necesitan una voz distinta.',
    },
  ];

  protected readonly activeTab = signal('pergamino');

  protected readonly activeTabContent = computed(
    () => this.tabs.find((tab) => tab.id === this.activeTab()) ?? this.tabs[0],
  );

  protected readonly profileOpen = signal(false);
  protected readonly profileEndOpen = signal(false);

  protected readonly copiedId = signal<string | null>(null);

