import {Directive, InputSignal, signal} from "@angular/core";

/**
 * Clase base para los componentes proyectados dentro de `<adyd-form>` que
 * aportan valores extra al payload de guardado.
 *
 * El componente concreto debe declarar su propio input `fieldName` y, opcionalmente,
 * sobreescribir `reset()` para limpiar su estado interno:
 * ```ts
 * @Component({providers: [{provide: AdydFormField, useExisting: forwardRef(() => MiComponente)}]})
 * export class MiComponente extends AdydFormField<string> {
 *   public readonly fieldName = input<string>('extra');
 * }
 * ```
 */
@Directive()
export abstract class AdydFormField<T extends string | number | File = string | number> {
    /** Clave con la que el valor viajará en el payload del formulario. */
    public abstract readonly fieldName: InputSignal<string>;

    private readonly value = signal<T | null>(null);

    /** Valor actual que se enviará al guardar. */
    public readonly fieldValue = this.value.asReadonly();

    /** Actualiza el valor pendiente de enviar (uso interno del componente). */
    protected setFieldValue(value: T | null): void {
        this.value.set(value);
    }

    /** Descarta el valor pendiente tras un guardado correcto. */
    public reset(): void {
        this.value.set(null);
    }
}

import {Directive, input, model, output} from '@angular/core';

/**
 * Contrato genérico para aportar valores extra al payload de `adyd-form`.
 *
 * Cualquier elemento o componente proyectado dentro de `<adyd-form>` puede usarlo:
 * ```html
 * <adyd-form ...>
 *   <mi-componente [adydFormField]="'campo'" [adydFormFieldValue]="valor()" />
 * </adyd-form>
 * ```
 * Los componentes que quieran gestionarlo internamente (como `adyd-img-editable`)
 * pueden aplicarlo con `hostDirectives` e inyectar esta directiva.
 */
@Directive({
    selector: '[adydFormField]',
})
export class AdydFormFieldDirective<T extends string | number | File = string | number | File> {
    /** Clave con la que el valor viajará en el payload del formulario. */
    public readonly fieldName = input.required<string>({alias: 'adydFormField'});

    /** Valor que se enviará al guardar. */
    public readonly fieldValue = model<T | null>(null, {alias: 'adydFormFieldValue'});

    /** Se emite cuando `adyd-form` descarta el valor tras un guardado correcto. */
    public readonly cleared = output<void>();

    public reset(): void {
        this.fieldValue.set(null);
        this.cleared.emit();
    }
}

import {Directive, TemplateRef, inject, input} from '@angular/core';

@Directive({
  selector: 'ng-template[adydTab]',
})
export class AdydTab {

  public readonly title = input.required<string>();

  public readonly template = inject<TemplateRef<unknown>>(TemplateRef);
}

import {Directive, ElementRef, effect, input, OnDestroy, OnInit} from '@angular/core';
import * as bootstrap from 'bootstrap';

@Directive({
  selector: '[tooltipText]',
  standalone: true
})
export class AdydTooltipDirective implements OnInit, OnDestroy {

  tooltipText = input.required<string>();
  tooltipPlacement = input<string>('top');
  private tooltipInstance?: bootstrap.Tooltip;

  constructor(private elementRef: ElementRef) {}

  ngOnInit() {
    if (this.tooltipText()) {
      this.elementRef.nativeElement.setAttribute('data-bs-toggle', 'tooltip');
      this.elementRef.nativeElement.setAttribute('data-bs-placement', this.tooltipPlacement());
      this.elementRef.nativeElement.setAttribute('data-bs-title', this.tooltipText());
      try {
        this.tooltipInstance = new bootstrap.Tooltip(this.elementRef.nativeElement);
      } catch (e) {
        console.error('No se pudo inicializar el tooltip de Bootstrap', e);
      }
    }
  }

  ngOnDestroy() {
    if (this.tooltipInstance) {
      this.tooltipInstance.dispose();
    }
  }

}

