.content {
  display: flex;
  justify-content: center;
  align-items: center;
  flex-direction: column;
  border: none;
}

/* Borderless forms - use alongside Bootstrap */
.borderless-form {
  border: none !important;
  box-shadow: none !important;
  padding: 0;
  margin: 0;
  background: transparent;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
