  padding: 0;
  background: transparent;
  width: 100%;
  max-width: 200px;
  text-align: center;
}

.borderless-form .form-control:focus,
.borderless-form .form-text:focus {
  border: none !important;
  box-shadow: none !important;
}

.borderless-form .mb-3 {
  width: 100%;
  display: flex;
  justify-content: center;
  align-items: center;
}

.borderless-form .btn {
  margin-top: 8px;
  display: flex;
  justify-content: center;
  align-items: center;
}

/* Carousel --------------------------------------------------------------- */

.adyd-carousel {
  position: relative;
  padding: 0.75rem 1rem;
}

.adyd-carousel__viewport {
  overflow: hidden;
}

.adyd-carousel__track {
  display: flex;
  gap: 1rem;
  width: max-content;
  will-change: transform;
  transition: transform 0.45s cubic-bezier(0.4, 0, 0.2, 1);
}

.adyd-carousel__item {
  position: relative;
  flex-grow: 0;
  flex-shrink: 0;
  flex-basis: var(--adyd-carousel-item-width, 220px);
  border-radius: 0.5rem;
  transform: scale(1);
  transform-origin: center;
  transition:
    transform 0.3s cubic-bezier(0.4, 0, 0.2, 1),
    box-shadow 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}

.adyd-carousel__item:hover,
.adyd-carousel__item:focus-within {
  z-index: 2;
  transform: scale(1.07);
  box-shadow: 0 1rem 1.5rem rgba(0, 0, 0, 0.4);
}

.adyd-carousel__item :is(.card, .card-img-top) {
  border-radius: 0.5rem;
}

.adyd-carousel__trigger {
  display: block;
  width: 100%;
  padding: 0;
  background: none;
  border: 0;
  border-radius: inherit;
  cursor: pointer;
}

.adyd-carousel__trigger:focus-visible {
  outline: 2px solid #0d6efd;
  outline-offset: 3px;
}

.adyd-carousel__control {
  position: absolute;
  top: 50%;
  z-index: 3;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 2.5rem;
  height: 2.5rem;
  padding: 0;
  color: #fff;
  background: rgba(0, 0, 0, 0.55);
  border: 0;
  border-radius: 50%;
  opacity: 0.85;
  transform: translateY(-50%);
  transition:
    opacity 0.2s ease,
    background-color 0.2s ease;
}

.adyd-carousel__control:hover {
  opacity: 1;
  background: rgba(0, 0, 0, 0.75);
}

.adyd-carousel__control--prev {
  left: 1rem;
}

.adyd-carousel__control--next {
  right: 1rem;
}

@media (prefers-reduced-motion: reduce) {
  .adyd-carousel__track,
  .adyd-carousel__item {
    transition: none;
  }
}

/* Lightbox --------------------------------------------------------------- */

.adyd-carousel__lightbox {
  width: min(92vw, 32rem);
  max-width: min(92vw, 32rem);
  padding: 0;
  overflow: visible;
  background: transparent;
  border: 0;
  opacity: 0;
  scale: 0.94;
  transition:
    opacity 0.28s cubic-bezier(0.4, 0, 0.2, 1),
    scale 0.28s cubic-bezier(0.4, 0, 0.2, 1),
    overlay 0.28s cubic-bezier(0.4, 0, 0.2, 1) allow-discrete,
    display 0.28s cubic-bezier(0.4, 0, 0.2, 1) allow-discrete;
}

.adyd-carousel__lightbox[open] {
  opacity: 1;
  scale: 1;
}

@starting-style {
  .adyd-carousel__lightbox[open] {
    opacity: 0;
    scale: 0.94;
  }
}

.adyd-carousel__lightbox::backdrop {
  background: rgba(0, 0, 0, 0.72);
  opacity: 0;
  transition:
    opacity 0.28s ease,
    overlay 0.28s ease allow-discrete,
    display 0.28s ease allow-discrete;
}

.adyd-carousel__lightbox[open]::backdrop {
  opacity: 1;
}

@starting-style {
