  protected copy(id: string, code: string): void {
    void navigator.clipboard?.writeText(code).catch(() => undefined);
    this.copiedId.set(id);
    window.setTimeout(() => {
      if (this.copiedId() === id) {
        this.copiedId.set(null);
      }
    }, 1600);
  }
}

